class Tables
{
    public:
     Item::TbItem TbItem;
     Item::TbWeapon TbWeapon;
     Item::TbArmor TbArmor;
     Character::TbCharacter TbCharacter;
     Uni::TbLocalization TbLocalization;
     Gameplay::TbAbility TbAbility;

    bool load(::luban::Loader<::luban::ByteBuf> loader)
    {
        ::luban::ByteBuf buf;
        buf.clear();
        if (!loader(buf, "item_tbitem")) return false;
        if (!TbItem.load(buf)) return false;
        buf.clear();
        if (!loader(buf, "item_tbweapon")) return false;
        if (!TbWeapon.load(buf)) return false;
        buf.clear();
        if (!loader(buf, "item_tbarmor")) return false;
        if (!TbArmor.load(buf)) return false;
        buf.clear();
        if (!loader(buf, "character_tbcharacter")) return false;
        if (!TbCharacter.load(buf)) return false;
        buf.clear();
        if (!loader(buf, "uni_tblocalization")) return false;
        if (!TbLocalization.load(buf)) return false;
        buf.clear();
        if (!loader(buf, "gameplay_tbability")) return false;
        if (!TbAbility.load(buf)) return false;
        return true;
    }
};



